using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Threading;
using Newtonsoft.Json.Linq;
namespace AICad.Contracts;
public sealed class ContentStore {
 readonly string appRoot;string Root(string kind)=>WarehousePaths.Folder(appRoot,kind);public ContentStore(string contentRoot){appRoot=Path.GetFullPath(contentRoot);}
 string Base(string kind,string id){if(kind!="skills"&&kind!="templates"&&kind!="standards")throw new CadException("INVALID_KIND","Unsupported content kind.");return Path.Combine(Root("packages"),kind,Json.Name(id));}
 public static string VersionName(string v){if(!Version.TryParse(v,out var parsed)||parsed.ToString()!=v||v.Contains(".."))throw new CadException("INVALID_VERSION","Canonical numeric version required.");return v;}
 public string Active(string kind,string id){string file=Path.Combine(Base(kind,id),"active.json");if(File.Exists(file))return Json.Read<JObject>(File.ReadAllText(file)).Value<string>("version")!;if(kind=="standards")throw new CadException("VERSION_NOT_FOUND",id);return kind=="skills"?Json.Read<SkillDefinition>(File.ReadAllText(Path.Combine(Root("skills"),Json.Name(id),"manifest.json"))).Version:Json.Read<TemplateProfile>(File.ReadAllText(Path.Combine(Root("template-library"),Json.Name(id)+".json"))).Version;}
 public bool Enabled(string id){string p=Path.Combine(Base("skills",id),"enabled.json");return File.Exists(p)?Json.Read<JObject>(File.ReadAllText(p)).Value<bool>("enabled"):Skill(id).Enabled;}
 public void SetEnabled(string id,bool enabled){_ = Skill(id);Json.Atomic(Path.Combine(Base("skills",id),"enabled.json"),new{enabled});}
 public T Read<T>(string kind,string id,string? version=null){version=VersionName(version??Active(kind,id));string file=Path.Combine(Base(kind,id),version,"content.json");if(File.Exists(file)){var value=Json.Read<T>(File.ReadAllText(file));string expected=File.ReadAllText(Path.Combine(Path.GetDirectoryName(file)!,"sha256.txt")).Trim();string fileDigest=Path.Combine(Path.GetDirectoryName(file)!,"file-sha256.txt");if(File.Exists(fileDigest)?Json.FileHash(file)!=File.ReadAllText(fileDigest).Trim():Json.Hash(value!)!=expected)throw new CadException("RESOURCE_CHANGED","Immutable resource checksum differs.");return value;}string fallback=kind=="skills"?Path.Combine(Root("skills"),Json.Name(id),"manifest.json"):Path.Combine(Root("template-library"),Json.Name(id)+".json");var obj=Json.Read<JObject>(File.ReadAllText(fallback));if(obj.Value<string>("Version")!=version)throw new CadException("VERSION_NOT_FOUND",id+"@"+version);return obj.ToObject<T>()!;}
 public SkillDefinition Skill(string id,string? v=null)=>Read<SkillDefinition>("skills",id,v);
 public TemplateProfile Template(string id,string? v=null)=>Read<TemplateProfile>("templates",id,v);
 public List<string> Ids(string kind){string legacy=kind=="standards"?Path.Combine(Root("packages"),"no-legacy-standards"):Root(kind=="skills"?"skills":"template-library");var ids=Directory.Exists(legacy)?(kind=="skills"?Directory.EnumerateDirectories(legacy).Select(Path.GetFileName):Directory.EnumerateFiles(legacy,"*.json").Select(Path.GetFileNameWithoutExtension)):Enumerable.Empty<string>();string package=Path.Combine(Root("packages"),kind);if(Directory.Exists(package))ids=ids.Concat(Directory.EnumerateDirectories(package).Where(p=>File.Exists(Path.Combine(p,"active.json"))).Select(Path.GetFileName));return ids.Where(x=>x!=null).Select(x=>x!).Distinct().OrderBy(x=>x).ToList();}
 public List<string> Versions(string kind,string id){var versions=new List<string>();string dir=Base(kind,id);if(Directory.Exists(dir))versions.AddRange(Directory.EnumerateDirectories(dir).Select(Path.GetFileName).Where(x=>Version.TryParse(x,out _)).Select(x=>x!));try{versions.Add(Active(kind,id));}catch(IOException){}catch(CadException)when(kind=="standards"){}return versions.Distinct().OrderBy(x=>new Version(x)).ToList();}
 public void Publish<T>(string kind,string id,string version,T value,string? integrityHash=null){if(kind!="skills"&&kind!="templates"&&kind!="standards")throw new CadException("INVALID_KIND","Unsupported content kind.");version=VersionName(version);string dir=Path.Combine(Base(kind,id),version);using var mutex=new Mutex(false,"Local\\AICadContent_"+Json.Hash(Base(kind,id)));bool held=false;try{try{held=mutex.WaitOne(2000);}catch(AbandonedMutexException){held=true;}if(!held)throw new CadException("BUSY","Resource publication is busy.");if(Directory.Exists(dir))throw new CadException("VERSION_EXISTS","Published versions cannot be replaced.");string staging=dir+"-staging-"+Guid.NewGuid().ToString("N");Directory.CreateDirectory(staging);Json.Atomic(Path.Combine(staging,"content.json"),value!);File.WriteAllText(Path.Combine(staging,"sha256.txt"),integrityHash??Json.Hash(value!));File.WriteAllText(Path.Combine(staging,"file-sha256.txt"),Json.FileHash(Path.Combine(staging,"content.json")));if(!Path.GetFullPath(staging).StartsWith(Path.GetFullPath(Base(kind,id))+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase)||!Path.GetFullPath(dir).StartsWith(Path.GetFullPath(Base(kind,id))+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))throw new CadException("UNSAFE_PATH","Content version path escaped package.");Directory.Move(staging,dir);Json.Atomic(Path.Combine(Base(kind,id),"active.json"),new{version});}finally{if(held)mutex.ReleaseMutex();}}
 public void Activate(string kind,string id,string version){if(kind=="skills")_ = Skill(id,version);else if(kind=="templates")_ = Template(id,version);else throw new CadException("INVALID_KIND",kind);Json.Atomic(Path.Combine(Base(kind,id),"active.json"),new{version=VersionName(version)});}
}
